"""Flash-attention kernel variants for cubin bundle lookup.

Single source of truth for the variant-key format used by both the
cubin-bundle builder in `scripts/precompile/cubin_bundles.py` and the
runtime dispatch in `dispatch.py`. Mirrors the pattern `MoeVariant` set
up in `cute_moe/config.py`.

Three dataclasses, matching the three kernel classes that survive the
PR #22 deletion:

- `FlashAttnVariant` — `FlashAttentionForwardSm90` /
  `FlashAttentionForwardSm100` / `FlashAttentionDecodeSm90`.
- `FlashAttnSm80ForwardVariant` — `FlashAttentionForwardSm80` (dense
  prefill for sm_80 / sm_86 / sm_87 / sm_89 / sm_120).
- `FlashAttnDecodePersistentSplitFusedVariant` —
  `FlashAttentionDecodePersistentSplitFused` (small-batch
  decode fast-path during CUDA graph capture).
"""

from dataclasses import dataclass
from functools import cached_property
from typing import Literal, Optional


FORWARD_MAX_VALUE_DIM_PER_CTA = 256

# Mask variants whose mask_mod reads an aux tensor (block_sequence_ids for
# block_bidirectional; the length-2 [window_q, window_kv] widths for
# windowed_blockdiag). These compile with has_aux_tensors=True and pack the tensor
# as a trailing memref; the dispatch layer must not bail when aux_tensors is
# provided for them.
MASKS_WITH_AUX = frozenset({"block_bidirectional", "windowed_blockdiag"})

_SM80_DENSE_BF16_TILES: dict[tuple[int, bool], tuple[int, int]] = {
    (56, False): (64, 64),
    # Tried 64x64 and 128x64 for SM89 S1500/H20/D64 at B1/2/4/8:
    # 64x64 ranged from 6.10% faster to 2.92% slower, while 128x64 was
    # only 0.52-0.95% faster (<=0.23 ms over 32 layers); keeping 128x128.
    (72, False): (128, 64),
    (96, False): (64, 32),
    (128, False): (128, 32),
    (64, True): (64, 64),
    # Four SM80 MMA warps cover 64 query rows. A 32-row tile leaves two
    # warps aliasing the same output rows, which made identical HD512
    # launches race. Keep the 96 KiB shared-memory footprint by narrowing K.
    (512, True): (64, 16),
}


def can_pack_gqa_forward(
    *,
    qhead_per_kvhead: int,
    tile_m: int,
    mask_mod_name: Optional[str],
) -> bool:
    """Whether a forward variant can use the packed-GQA query layout.

    Packing folds each query-head group into the M dimension. The tile must
    therefore contain a whole number of groups, and masks that address true
    sequence positions cannot use the transformed M coordinate. Keep this
    rule shared by runtime dispatch and AOT compilation so a variant key can
    never resolve to a cubin built for a different query layout.
    """

    if qhead_per_kvhead < 1:
        raise ValueError(
            "qhead_per_kvhead must be positive, "
            f"got {qhead_per_kvhead}"
        )
    if tile_m < 1:
        raise ValueError(f"tile_m must be positive, got {tile_m}")
    return (
        qhead_per_kvhead > 1
        and mask_mod_name is None
        and tile_m % qhead_per_kvhead == 0
    )


@dataclass(frozen=True)
class FlashAttnVariant:
    """Forward / decode variant for the SM90 or SM100 kernel classes.

    Identifies one shipped cubin in `bundles/flash_attn/`. Both `forward`
    variants — sm_90 and sm_100 — share this dataclass because they have
    the same variant-key schema; the arch tag baked into the key
    (`sm90` vs `sm100`) disambiguates which kernel class to instantiate.
    """

    kind: Literal["forward_sm90", "forward_sm100", "decode_sm90"]
    dtype_name: str              # "bf16"
    dtype_kv_name: Optional[str] # "bf16" / "fp8_e4m3" / None (defaults to dtype_name)
    head_dim: int
    causal: bool
    mask_mod_name: Optional[str] # "block_bidirectional" or None
    paged_kv_non_tma: bool
    seqused_q: bool = False
    dense_seqused_k: bool = False
    cu_seqlens_q: bool = False
    cu_seqlens_k: bool = False
    qhead_per_kvhead: int = 1
    local: bool = False
    tile_m: int = 128
    tile_n: int = 128
    num_stages: int = 2
    value_splits: int = 1
    pack_gqa: Optional[bool] = None

    def __post_init__(self) -> None:
        if self.seqused_q and self.cu_seqlens_q:
            raise ValueError("seqused_q and cu_seqlens_q are mutually exclusive")
        if self.dense_seqused_k and self.paged_kv_non_tma:
            raise ValueError("dense used-K lengths and paged KV are mutually exclusive")
        if self.paged_kv_non_tma and self.cu_seqlens_k:
            raise ValueError("paged KV and cu_seqlens_k are mutually exclusive")
        if self.value_splits < 1 or self.head_dim % self.value_splits:
            raise ValueError(
                "value_splits must be positive and divide head_dim, got "
                f"head_dim={self.head_dim}, value_splits={self.value_splits}"
            )
        if self.value_splits > 1 and self.kind not in (
            "forward_sm90",
            "forward_sm100",
        ):
            raise ValueError("value_splits are implemented only for forward attention")
        if self.value_splits > 1 and self.seqused_q:
            raise ValueError(
                "value-split attention does not support padded-Q active extents"
            )
        if (
            self.kind in ("forward_sm90", "forward_sm100")
            and self.head_dim // self.value_splits
            > FORWARD_MAX_VALUE_DIM_PER_CTA
        ):
            raise ValueError(
                "forward AOT variants require value head dimension per CTA "
                f"<= {FORWARD_MAX_VALUE_DIM_PER_CTA}, got "
                f"{self.head_dim // self.value_splits}"
            )

    @property
    def uses_packed_gqa(self) -> bool:
        if self.pack_gqa is not None:
            return self.pack_gqa
        return can_pack_gqa_forward(
            qhead_per_kvhead=self.qhead_per_kvhead,
            tile_m=self.tile_m,
            mask_mod_name=self.mask_mod_name,
        )

    @cached_property
    def variant_key(self) -> str:
        # Suffix rules match the post-#22 `.so` filename encoding so the
        # cubin keys are a drop-in for the old precompiled filenames.
        # `decode` always emits `_{dtype_kv_name}` even when KV matches Q
        # dtype — the decode family was shipped that way under the old
        # precompile script and tests monkeypatch against those names.
        if self.kind == "decode_sm90":
            dtype_kv = self.dtype_kv_name or self.dtype_name
            dtype_kv_str = f"_{dtype_kv}"
        else:
            dtype_kv_str = (
                f"_{self.dtype_kv_name}"
                if self.dtype_kv_name is not None and self.dtype_kv_name != self.dtype_name
                else ""
            )
        causal_str = "_causal" if self.causal else ""
        gqa_str = (
            f"_gqa{self.qhead_per_kvhead}"
            if self.qhead_per_kvhead != 1
            else ""
        )
        tile_str = ""
        if self.kind != "decode_sm90" and (
            self.tile_m != 128 or self.tile_n != 128 or self.num_stages != 2
        ):
            tile_str = f"_tm{self.tile_m}_tn{self.tile_n}_s{self.num_stages}"
        mask_str = f"_{self.mask_mod_name}" if self.mask_mod_name else ""
        local_str = "_local" if self.local else ""
        value_split_str = (
            f"_vsplit{self.value_splits}" if self.value_splits != 1 else ""
        )
        paged_str = "_paged" if self.paged_kv_non_tma else ""
        cu_seqlens_q_str = "_cuseqlensq" if self.cu_seqlens_q else ""
        cu_seqlens_k_str = "_cuseqlensk" if self.cu_seqlens_k else ""
        seqused_q_str = "_sequsedq" if self.seqused_q else ""
        seqused_k_str = "_sequsedk" if self.dense_seqused_k else ""
        return (
            f"{self.kind}_{self.dtype_name}{dtype_kv_str}"
            f"_hd{self.head_dim}{gqa_str}{tile_str}"
            f"{causal_str}{mask_str}{local_str}{value_split_str}{paged_str}"
            f"{cu_seqlens_q_str}{cu_seqlens_k_str}{seqused_q_str}"
            f"{seqused_k_str}"
        )

    @property
    def needs_aux_tensors(self) -> bool:
        """Whether the mask reads a per-token aux tensor (block_sequence_ids).

        Such variants compile with ``has_aux_tensors=True`` and carry one extra
        trailing memref (the int32 block-id tensor) in the cubin ABI.
        """
        return self.mask_mod_name in MASKS_WITH_AUX


@dataclass(frozen=True)
class FlashAttnSm80ForwardVariant:
    """Prefill variant for `FlashAttentionForwardSm80`.

    Used on sm_80/86/87/89/120. Routed to via
    `interface._flash_attn_fwd` when `sm8x_prefill.is_eligible` returns
    True.

    `dtype_kv_name=None` means KV matches Q dtype (historical default).
    `dtype_kv_name="fp8_e4m3"` selects the dual-smem FP8 path: cp.async
    into FP8 smem, convert to BF16 staging smem, then ldmatrix / mma as
    usual. See `docs/SM80_FP8_KV_DESIGN.md`.
    """

    dtype_name: str                    # "bf16"
    head_dim: int
    causal: bool
    mask_mod_name: Optional[str]       # "block_bidirectional" or None
    dtype_kv_name: Optional[str] = None  # "fp8_e4m3" or None (= dtype_name)
    paged_kv_non_tma: bool = False
    seqused_q: bool = False
    local: bool = False
    qhead_per_kvhead: int = 1

    @property
    def _dense_bf16(self) -> bool:
        return (
            self.mask_mod_name is None
            and self.dtype_kv_name is None
            and not self.paged_kv_non_tma
            and not self.seqused_q
            and not self.local
        )

    @property
    def tile_m(self) -> int:
        """Q tile size for the SM80-family kernel."""
        return self._tile_shape[0]

    @property
    def tile_n(self) -> int:
        """K/V tile size for the SM80-family kernel.

        Dense BF16 head dims follow measured SM86 production-launch
        timings. Existing paged, masked, and FP8-KV variants stay on the
        established 128x128 path.
        """
        return self._tile_shape[1]

    @property
    def _tile_shape(self) -> tuple[int, int]:
        if (
            self.paged_kv_non_tma
            and self.causal
            and self.head_dim == 256
            and self.qhead_per_kvhead > 1
        ):
            return (64, 64)
        if self.local and self.dtype_name == "bf16" and self.dtype_kv_name is None:
            if self.head_dim == 256:
                return (64, 64)
            if self.head_dim == 64:
                return (64, 64)
        if self._dense_bf16:
            return _SM80_DENSE_BF16_TILES.get((self.head_dim, self.causal), (128, 128))
        return (128, 128)

    @cached_property
    def variant_key(self) -> str:
        dtype_kv_str = (
            f"_{self.dtype_kv_name}"
            if self.dtype_kv_name is not None and self.dtype_kv_name != self.dtype_name
            else ""
        )
        causal_str = "_causal" if self.causal else ""
        local_str = "_local" if self.local else ""
        mask_str = f"_{self.mask_mod_name}" if self.mask_mod_name else ""
        paged_str = "_paged" if self.paged_kv_non_tma else ""
        seqused_q_str = "_sequsedq" if self.seqused_q else ""
        gqa_str = (
            f"_gqa{self.qhead_per_kvhead}"
            if self.qhead_per_kvhead != 1
            else ""
        )
        if self.tile_m == 128 and self.tile_n == 128:
            tile_str = ""
        elif self.tile_m == 128:
            tile_str = f"_tn{self.tile_n}"
        else:
            tile_str = f"_tm{self.tile_m}_tn{self.tile_n}"
        return (
            f"forward_sm80_{self.dtype_name}{dtype_kv_str}"
            f"_hd{self.head_dim}{gqa_str}{tile_str}{causal_str}"
            f"{local_str}{mask_str}{paged_str}{seqused_q_str}"
        )

    @property
    def needs_aux_tensors(self) -> bool:
        """Whether the mask reads a per-token aux tensor (block_sequence_ids).

        Block-bidirectional SM80 variants compile with ``has_aux_tensors=True``
        and carry one trailing int32 ``block_sequence_ids`` memref.
        """
        return self.mask_mod_name in MASKS_WITH_AUX


@dataclass(frozen=True)
class FlashAttnDecodePersistentSplitFusedVariant:
    """Persistent split-fused decode variant for
    `FlashAttentionDecodePersistentSplitFused`.

    Engaged during CUDA graph capture for small batches where the
    baseline grid underfills the GPU. Variant tuple identifies a
    specific (num_splits, split_tokens) compile-time point; the device
    SM count is a runtime launch parameter.
    """

    dtype_name: str              # "bf16"
    dtype_kv_name: str           # "bf16" / "fp8_e4m3"
    head_dim: int
    num_splits: int
    split_tokens: int

    @cached_property
    def variant_key(self) -> str:
        return (
            f"persistent_split_fused_decode_{self.dtype_name}_{self.dtype_kv_name}"
            f"_hd{self.head_dim}_s{self.num_splits}_t{self.split_tokens}"
        )


# ---------------------------------------------------------------------------
# Shipped variant inventory — the kernel/arch combinations compiled into
# `bundles/flash_attn/` and dispatched at runtime. Imported by both the
# cubin-bundle builder and the runtime resolver.
# ---------------------------------------------------------------------------

_FORWARD_DECODE_VARIANTS_COMMON = [
    # Dense causal MHA.  This is the canonical short-prefix self-attention
    # primitive; sequence and batch extents remain runtime dynamic.
    ("forward", "bf16", None, 64, True, None, False, False),
    # Text forward (causal, paged, BF16 KV)
    ("forward", "bf16", None, 64, True, None, True, False),
    ("forward", "bf16", None, 64, True, None, True, True),
    # Text forward (causal, paged, FP8 KV)
    ("forward", "bf16", "fp8_e4m3", 64, True, None, True, False),
    ("forward", "bf16", "fp8_e4m3", 64, True, None, True, True),
    # Text forward (general block-bidirectional vision mask, paged, BF16 KV).
    # Reads block_sequence_ids via aux_tensors.
    ("forward", "bf16", None, 64, False, "block_bidirectional", True, False),
    ("forward", "bf16", None, 64, False, "block_bidirectional", True, True),
    # Text forward (block-bidirectional vision mask, paged, FP8 KV) — Moondream
    # runs an FP8 KV cache, so it also has FP8 variants.
    ("forward", "bf16", "fp8_e4m3", 64, False, "block_bidirectional", True, False),
    ("forward", "bf16", "fp8_e4m3", 64, False, "block_bidirectional", True, True),
    # Vision forward (non-paged, non-causal). hd32 is RF-DETR's transformer
    # decoder self-attention (d_model 256 / 8 heads); it is an exact multiple of
    # 16, so the forward kernel needs no head-dim OOB predication (identical path
    # to hd64). hd56 pads to 64 (OOB predicated) and is not currently emitted by
    # any shipped model — kept in the runtime allow-set for back-compat only.
    ("forward", "bf16", None, 32, False, None, False, False),
    ("forward", "bf16", None, 56, False, None, False, False),
    ("forward", "bf16", None, 64, False, None, False, False),
    ("forward", "bf16", None, 72, False, None, False, False),
    ("forward", "bf16", None, 96, False, None, False, False),
    ("forward", "bf16", None, 128, False, None, False, False),
]

# Head dims covered by the non-paged, non-causal, MHA "vision dense forward"
# cubin family above. The runtime dispatch (interface_sm90._try_cubin_launch)
# gates on this exact set so it only claims a native launch for head dims that
# ship a forward_sm90 / forward_sm100 `.so`.
#
# DERIVED from the shipped inventory, not restated: a hand-written copy of these
# head dims is a second list that has to be edited in lockstep with the first,
# and the failure mode when it isn't is a *runtime* "resolved SM90 forward
# attention artifact is unavailable" on a production host with JIT off.
VISION_DENSE_FORWARD_HEAD_DIMS = tuple(sorted({
    hd
    for (_, dt, dt_kv, hd, causal, mask, paged, sq) in _FORWARD_DECODE_VARIANTS_COMMON
    if dt == "bf16" and dt_kv is None
    and not causal and mask is None and not paged and not sq
}))

_QWEN_GQA_FORWARD_VARIANTS = [
    # Qwen 3.5 text full-attention prefill: 8 Q heads / 2 KV heads, hd=256.
    # Qwen 3.6 35B text full-attention prefill: 16 Q heads / 2 KV heads, hd=256.
    # Qwen 3.5 27B uses 24 Q heads / 4 KV heads (GQA factor 6), hd=256.
    # The default 128x128x2 SM90 forward tile exceeds shared-memory budget at
    # hd=256, so this variant uses a smaller tile.
    # Tried tm128_tn64_s2: 1.04x/1.19x slower at S=512/768 on H100.
    # Tried tm64_tn32_s2: 0.96x at S=512 but 43x slower at S=768; keeping 64x64.
    ("forward", "bf16", None, 256, True, None, True, False, False, 4, 64, 64, 2),
    ("forward", "bf16", None, 256, True, None, True, False, True, 4, 64, 64, 2),
    ("forward", "bf16", None, 256, True, None, True, False, False, 6, 64, 64, 2),
    ("forward", "bf16", None, 256, True, None, True, False, True, 6, 64, 64, 2),
    ("forward", "bf16", None, 256, True, None, True, False, False, 8, 64, 64, 2),
    ("forward", "bf16", None, 256, True, None, True, False, True, 8, 64, 64, 2),
]

# Runtime-window GQA forward shapes validated for SM90.  This is the single
# source for both shipped AOT inventory and runtime tile selection.
_HD256_GQA_GROUP_SIZES = (2, 4, 8)

SM90_LOCAL_GQA_FORWARD_CONFIGS = tuple(
    # (head_dim, qheads_per_kvhead, tile_m, tile_n, stages)
    (256, group_size, 64, 64, 2)
    for group_size in _HD256_GQA_GROUP_SIZES
)

# Packed dense causal attention uses the HD256 runtime-window tiles plus the
# default 128x128x2 tile for HD128 (not yet tuned). Q and KV carry independent
# row offsets.
SM90_PACKED_CAUSAL_GQA_FORWARD_CONFIGS = (
    (128, 2, 128, 128, 2),
    *SM90_LOCAL_GQA_FORWARD_CONFIGS,
)

# Wide-value GQA needs multiple output owners to keep each CTA's value tile
# within the SM90 register/shared-memory envelope.  These are physical kernel
# configurations, not model identities; the provider resolves them from the
# semantic head geometry and storage layout.
SM90_WIDE_GQA_FORWARD_CONFIGS = (
    # (head_dim, qheads_per_kvhead, tile_m, tile_n, stages, value_splits)
    (512, 4, 64, 32, 1, 2),
    (512, 8, 64, 32, 1, 2),
)

_SM90_WIDE_GQA_FORWARD_LAYOUTS = (
    # (paged_kv, causal, cu_seqlens_q, cu_seqlens_k)
    (False, True, False, False),
    (False, True, True, True),
    (True, True, False, False),
)

# The local-window kernel accepts the same query domains with dense or paged
# KV. Keep the layouts separate from geometry so the inventory does not grow a
# one-off model shape. Paged KV carries the per-row used-K length; variable Q
# is represented by exactly one of a padded-row extent or packed offsets.
_SM90_LOCAL_GQA_FORWARD_LAYOUTS = (
    # (paged_kv, seqused_q, cu_seqlens_q, cu_seqlens_k)
    (False, False, False, False),
    (False, False, True, True),
    (True, False, False, False),
    (True, True, False, False),
    (True, False, True, False),
)

_QWEN_GQA_BLOCKBIDI_FORWARD_VARIANTS = [
    # Qwen 3.5 / Moondream 3 masked prefill: the block_bidirectional vision mask
    # over the GQA text decoder (16 Q / 4 KV — and the 16/2 layout — hd=256).
    # Non-causal + reads block_sequence_ids via aux_tensors. Served as the
    # non-packed GQA layout (pack-GQA would misindex the per-token aux tensor),
    # so each query head is an independent per-head masked problem. Same 64x64
    # tile as the causal hd256 GQA prefill (128x128x2 overflows smem at hd=256).
    # seqused_q present (per-request varlen Q) or absent (fixed-length prefill).
    ("forward", "bf16", None, 256, False, "block_bidirectional", True, False, False, 4, 64, 64, 2),
    ("forward", "bf16", None, 256, False, "block_bidirectional", True, True, False, 4, 64, 64, 2),
    ("forward", "bf16", None, 256, False, "block_bidirectional", True, False, False, 8, 64, 64, 2),
    ("forward", "bf16", None, 256, False, "block_bidirectional", True, True, False, 8, 64, 64, 2),
]

_DENSE_VARLEN_FORWARD_VARIANTS = [
    # Packed dense non-causal MHA. This covers
    # vision-style chunked self-attention without a Python per-chunk loop.
    ("forward", "bf16", None, 64, False, None, False, False, True, True, 1, 128, 128, 2),
    ("forward", "bf16", None, 72, False, None, False, False, True, True, 1, 128, 128, 2),
]

# Dense padded-prefix attention keeps Q fixed-shape and bounds K/V with a
# per-row runtime extent. These are physical head geometries shared by the
# SM90 and SM100 providers.
DENSE_USED_K_FORWARD_HEAD_DIMS = (64, 72)

# SAM2 windowed prefill: the non-paged, non-causal, MHA vision-dense forward with the
# block-diagonal windowed_blockdiag mask (G windows packed per flash batch element). Same
# 7-field shape as the mask-free vision-dense entries above (default 128x128x2 tile, qg=1),
# but reads the [window_q, window_kv] widths via aux_tensors. Shipped so production wheels
# (JIT off) resolve a native cubin instead of falling back to torch SDPA. SAM2's Hiera runs
# hd=96 uniformly; the other vision-dense dims are shipped for windowed encoders generally.
# sm90 only for now (device-verified on H100); a B200/sm100 window-pack follows separately.
_WINDOWED_BLOCKDIAG_FORWARD_VARIANTS = [
    ("forward", "bf16", None, 64, False, "windowed_blockdiag", False, False),
    ("forward", "bf16", None, 72, False, "windowed_blockdiag", False, False),
    ("forward", "bf16", None, 96, False, "windowed_blockdiag", False, False),
    ("forward", "bf16", None, 128, False, "windowed_blockdiag", False, False),
]

_DECODE_VARIANTS = [
    # Text decode (BF16 KV): MHA plus Qwen-style GQA groups.
    *[
        ("decode", "bf16", "bf16", hd, True, None, True, False, qg)
        for hd in (64, 128, 256)
        for qg in (1, 2, 4, 8)
    ],
    ("decode", "bf16", "bf16", 256, True, None, True, False, 6),
    # Text decode (FP8 KV): existing hd64 MHA fastpath.
    ("decode", "bf16", "fp8_e4m3", 64, True, None, True, False, 1),
]

_LOCAL_DECODE_VARIANTS = [
    # Gemma 4 sliding-window decode.
    ("decode", "bf16", "bf16", 256, False, None, True, False, 2),
    ("decode", "bf16", "bf16", 256, False, None, True, False, 8),
]


def build_sm90_variants() -> list[FlashAttnVariant]:
    """All forward + decode variants shipped for SM90."""
    out: list[FlashAttnVariant] = []
    for (_, dt, dt_kv, hd, causal, mask, paged, sq) in (
        _FORWARD_DECODE_VARIANTS_COMMON + _WINDOWED_BLOCKDIAG_FORWARD_VARIANTS
    ):
        out.append(FlashAttnVariant(
            kind="forward_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq,
        ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, cuseq, qg, tile_m, tile_n, stages) in (
        _QWEN_GQA_FORWARD_VARIANTS + _QWEN_GQA_BLOCKBIDI_FORWARD_VARIANTS
    ):
        out.append(FlashAttnVariant(
            kind="forward_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, cu_seqlens_q=cuseq, qhead_per_kvhead=qg,
            tile_m=tile_m, tile_n=tile_n, num_stages=stages,
        ))
    for hd, qg, tile_m, tile_n, stages in SM90_LOCAL_GQA_FORWARD_CONFIGS:
        for paged, seqused_q, cu_seqlens_q, cu_seqlens_k in _SM90_LOCAL_GQA_FORWARD_LAYOUTS:
            out.append(FlashAttnVariant(
                kind="forward_sm90",
                dtype_name="bf16", dtype_kv_name=None, head_dim=hd,
                causal=False, mask_mod_name=None, paged_kv_non_tma=paged,
                seqused_q=seqused_q, cu_seqlens_q=cu_seqlens_q,
                cu_seqlens_k=cu_seqlens_k,
                qhead_per_kvhead=qg, local=True,
                tile_m=tile_m, tile_n=tile_n, num_stages=stages,
            ))
    for hd, qg, tile_m, tile_n, stages in SM90_PACKED_CAUSAL_GQA_FORWARD_CONFIGS:
        out.append(FlashAttnVariant(
            kind="forward_sm90",
            dtype_name="bf16", dtype_kv_name=None, head_dim=hd,
            causal=True, mask_mod_name=None, paged_kv_non_tma=False,
            cu_seqlens_q=True, cu_seqlens_k=True,
            qhead_per_kvhead=qg,
            tile_m=tile_m, tile_n=tile_n, num_stages=stages,
        ))
    for hd, qg, tile_m, tile_n, stages, value_splits in SM90_WIDE_GQA_FORWARD_CONFIGS:
        for paged, causal, cu_seqlens_q, cu_seqlens_k in _SM90_WIDE_GQA_FORWARD_LAYOUTS:
            out.append(FlashAttnVariant(
                kind="forward_sm90",
                dtype_name="bf16", dtype_kv_name=None, head_dim=hd,
                causal=causal, mask_mod_name=None,
                paged_kv_non_tma=paged, qhead_per_kvhead=qg,
                cu_seqlens_q=cu_seqlens_q, cu_seqlens_k=cu_seqlens_k,
                tile_m=tile_m, tile_n=tile_n, num_stages=stages,
                value_splits=value_splits,
            ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, cuseq_q, cuseq_k, qg, tile_m, tile_n, stages) in (
        _DENSE_VARLEN_FORWARD_VARIANTS
    ):
        out.append(FlashAttnVariant(
            kind="forward_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, cu_seqlens_q=cuseq_q, cu_seqlens_k=cuseq_k,
            qhead_per_kvhead=qg, tile_m=tile_m, tile_n=tile_n,
            num_stages=stages,
        ))
    # Dense padded-prefix attention. Q remains fixed-shape while a runtime
    # int32 length bounds the valid K/V prefix for every row.
    for head_dim in DENSE_USED_K_FORWARD_HEAD_DIMS:
        out.append(FlashAttnVariant(
            kind="forward_sm90",
            dtype_name="bf16", dtype_kv_name=None, head_dim=head_dim,
            causal=False, mask_mod_name=None, paged_kv_non_tma=False,
            dense_seqused_k=True,
        ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, qg) in _DECODE_VARIANTS:
        out.append(FlashAttnVariant(
            kind="decode_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, qhead_per_kvhead=qg,
        ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, qg) in _LOCAL_DECODE_VARIANTS:
        out.append(FlashAttnVariant(
            kind="decode_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, qhead_per_kvhead=qg, local=True,
        ))
    return out


def build_sm100_variants() -> list[FlashAttnVariant]:
    """Forward + decode variants shipped for SM100 (datacenter Blackwell,
    the only arch that uses the tcgen05 `FlashAttentionForwardSm100`)."""
    out: list[FlashAttnVariant] = []
    for (_, dt, dt_kv, hd, causal, mask, paged, sq) in _FORWARD_DECODE_VARIANTS_COMMON:
        out.append(FlashAttnVariant(
            kind="forward_sm100",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq,
        ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, cuseq_q, cuseq_k, qg, tile_m, tile_n, stages) in (
        _DENSE_VARLEN_FORWARD_VARIANTS
    ):
        out.append(FlashAttnVariant(
            kind="forward_sm100",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, cu_seqlens_q=cuseq_q, cu_seqlens_k=cuseq_k,
            qhead_per_kvhead=qg, tile_m=tile_m, tile_n=tile_n,
            num_stages=stages,
        ))
    for head_dim, group_sizes in (
        (128, (2,)),
        (256, _HD256_GQA_GROUP_SIZES),
    ):
        for qg in group_sizes:
            out.append(FlashAttnVariant(
                kind="forward_sm100",
                dtype_name="bf16", dtype_kv_name=None, head_dim=head_dim,
                causal=True, mask_mod_name=None, paged_kv_non_tma=False,
                cu_seqlens_q=True, cu_seqlens_k=True,
                qhead_per_kvhead=qg, tile_m=128, tile_n=128,
                num_stages=2, pack_gqa=False,
            ))
    for qg in _HD256_GQA_GROUP_SIZES:
        for paged, seqused_q, cu_seqlens_q, cu_seqlens_k in (
            _SM90_LOCAL_GQA_FORWARD_LAYOUTS
        ):
            out.append(FlashAttnVariant(
                kind="forward_sm100",
                dtype_name="bf16", dtype_kv_name=None, head_dim=256,
                causal=False, mask_mod_name=None, paged_kv_non_tma=paged,
                seqused_q=seqused_q, cu_seqlens_q=cu_seqlens_q,
                cu_seqlens_k=cu_seqlens_k, qhead_per_kvhead=qg, local=True,
                tile_m=128, tile_n=128, num_stages=2, pack_gqa=False,
            ))
    # Dense padded-prefix attention. Keep this ABI aligned with SM90: Q remains
    # fixed-shape while one runtime int32 extent bounds each K/V row.
    for head_dim in DENSE_USED_K_FORWARD_HEAD_DIMS:
        out.append(FlashAttnVariant(
            kind="forward_sm100",
            dtype_name="bf16", dtype_kv_name=None, head_dim=head_dim,
            causal=False, mask_mod_name=None, paged_kv_non_tma=False,
            dense_seqused_k=True,
        ))
    # hd256 GQA forward (the DFlash verify) -- ship these for sm100 too, so
    # production wheels (JIT off) can resolve a cubin instead of falling back.
    # The _compile_flash_attn_forward head_dim>=256 override compiles them
    # 128x128 non-packed (the tuple's 64x64 tile is only the SM90-tuned key).
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, cuseq, qg, tile_m, tile_n, stages) in (
        _QWEN_GQA_FORWARD_VARIANTS
    ):
        out.append(FlashAttnVariant(
            kind="forward_sm100",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, cu_seqlens_q=cuseq, qhead_per_kvhead=qg,
            tile_m=128, tile_n=128, num_stages=stages, pack_gqa=False,
        ))
    for hd, qg, _tile_m, _tile_n, _stages, value_splits in (
        SM90_WIDE_GQA_FORWARD_CONFIGS
    ):
        for paged, causal, cu_seqlens_q, cu_seqlens_k in (
            _SM90_WIDE_GQA_FORWARD_LAYOUTS
        ):
            out.append(FlashAttnVariant(
                kind="forward_sm100",
                dtype_name="bf16", dtype_kv_name=None, head_dim=hd,
                causal=causal, mask_mod_name=None,
                paged_kv_non_tma=paged,
                cu_seqlens_q=cu_seqlens_q, cu_seqlens_k=cu_seqlens_k,
                qhead_per_kvhead=qg, tile_m=128, tile_n=64,
                num_stages=1, value_splits=value_splits, pack_gqa=False,
            ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, qg) in _DECODE_VARIANTS:
        out.append(FlashAttnVariant(
            kind="decode_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, qhead_per_kvhead=qg,
        ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, qg) in _LOCAL_DECODE_VARIANTS:
        out.append(FlashAttnVariant(
            kind="decode_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, qhead_per_kvhead=qg, local=True,
        ))
    return out


def build_sm80_family_decode_variants() -> list[FlashAttnVariant]:
    """Decode variants for sm_80/86/87/89/120 (all share the SM90 decode
    kernel class — the `arch` param on `FlashAttentionDecodeSm90` handles
    the target)."""
    out: list[FlashAttnVariant] = []
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, qg) in _DECODE_VARIANTS:
        out.append(FlashAttnVariant(
            kind="decode_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, qhead_per_kvhead=qg,
        ))
    for (_, dt, dt_kv, hd, causal, mask, paged, sq, qg) in _LOCAL_DECODE_VARIANTS:
        out.append(FlashAttnVariant(
            kind="decode_sm90",
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            causal=causal, mask_mod_name=mask, paged_kv_non_tma=paged,
            seqused_q=sq, qhead_per_kvhead=qg, local=True,
        ))
    return out


def build_sm80_forward_variants() -> list[FlashAttnSm80ForwardVariant]:
    """SM80 prefill variants for sm_80/86/87/89/120."""
    return [
        # BF16 KV (vision and text paths).
        FlashAttnSm80ForwardVariant("bf16", 56, False, None),
        FlashAttnSm80ForwardVariant("bf16", 64, False, None),
        FlashAttnSm80ForwardVariant("bf16", 72, False, None),
        FlashAttnSm80ForwardVariant("bf16", 96, False, None),
        FlashAttnSm80ForwardVariant("bf16", 128, False, None),
        FlashAttnSm80ForwardVariant("bf16", 256, False, None, None, False, False, True),
        FlashAttnSm80ForwardVariant("bf16", 64, True, None),
        FlashAttnSm80ForwardVariant("bf16", 512, True, None),
        # Gemma 4 E4B uses 8 Q / 2 KV heads for both attention kinds.
        FlashAttnSm80ForwardVariant(
            "bf16", 512, True, None, qhead_per_kvhead=4,
        ),
        FlashAttnSm80ForwardVariant(
            "bf16", 512, True, None, qhead_per_kvhead=8,
        ),
        FlashAttnSm80ForwardVariant(
            "bf16", 256, False, None, local=True, qhead_per_kvhead=2,
        ),
        FlashAttnSm80ForwardVariant(
            "bf16", 256, False, None, local=True, qhead_per_kvhead=4,
        ),
        FlashAttnSm80ForwardVariant(
            "bf16", 256, False, None, local=True, qhead_per_kvhead=8,
        ),
        FlashAttnSm80ForwardVariant("bf16", 64, True, None, None, True),
        FlashAttnSm80ForwardVariant("bf16", 64, True, None, None, True, True),
        # Gemma 4 local decode on Ampere. The forward kernel handles Q length
        # one and reads sliding-window HD256 directly from the paged KV cache.
        FlashAttnSm80ForwardVariant(
            "bf16", 256, False, None,
            paged_kv_non_tma=True, local=True, qhead_per_kvhead=8,
        ),
        # Qwen 3.5 packed prefill on paged KV caches. Packed Q is split into
        # rows by the runtime wrapper; each row uses the native paged GQA
        # kernel instead of torch SDPA.
        FlashAttnSm80ForwardVariant(
            "bf16", 256, True, None,
            paged_kv_non_tma=True, qhead_per_kvhead=4,
        ),
        FlashAttnSm80ForwardVariant(
            "bf16", 256, True, None,
            paged_kv_non_tma=True, qhead_per_kvhead=6,
        ),
        FlashAttnSm80ForwardVariant(
            "bf16", 256, True, None,
            paged_kv_non_tma=True, qhead_per_kvhead=8,
        ),
        # FP8 KV (text paths only — vision runs don't store FP8 KV).
        FlashAttnSm80ForwardVariant("bf16", 64, True, None, "fp8_e4m3"),
        FlashAttnSm80ForwardVariant("bf16", 64, True, None, "fp8_e4m3", True),
        FlashAttnSm80ForwardVariant("bf16", 64, True, None, "fp8_e4m3", True, True),
        # block-bidirectional vision mask (reads aux).
        FlashAttnSm80ForwardVariant("bf16", 64, False, "block_bidirectional"),
        FlashAttnSm80ForwardVariant("bf16", 64, False, "block_bidirectional", None, True),
        FlashAttnSm80ForwardVariant("bf16", 64, False, "block_bidirectional", None, True, True),
        FlashAttnSm80ForwardVariant("bf16", 64, False, "block_bidirectional", "fp8_e4m3"),
        FlashAttnSm80ForwardVariant("bf16", 64, False, "block_bidirectional", "fp8_e4m3", True),
        FlashAttnSm80ForwardVariant("bf16", 64, False, "block_bidirectional", "fp8_e4m3", True, True),
    ]


def build_persistent_split_fused_variants() -> list[FlashAttnDecodePersistentSplitFusedVariant]:
    """Persistent split-fused decode variants."""
    out: list[FlashAttnDecodePersistentSplitFusedVariant] = []
    for (dt, dt_kv, hd, nsplits, split_tokens) in [
        # BF16 KV (num_splits 2-4, split_tokens 64 or 256)
        ("bf16", "bf16", 64, 2, 64),
        ("bf16", "bf16", 64, 2, 256),
        ("bf16", "bf16", 64, 3, 64),
        ("bf16", "bf16", 64, 3, 256),
        ("bf16", "bf16", 64, 4, 64),
        ("bf16", "bf16", 64, 4, 256),
        # FP8 KV
        ("bf16", "fp8_e4m3", 64, 2, 64),
        ("bf16", "fp8_e4m3", 64, 2, 256),
        ("bf16", "fp8_e4m3", 64, 3, 64),
        ("bf16", "fp8_e4m3", 64, 3, 256),
        ("bf16", "fp8_e4m3", 64, 4, 64),
        ("bf16", "fp8_e4m3", 64, 4, 256),
    ]:
        out.append(FlashAttnDecodePersistentSplitFusedVariant(
            dtype_name=dt, dtype_kv_name=dt_kv, head_dim=hd,
            num_splits=nsplits, split_tokens=split_tokens,
        ))
    return out


